// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.CreatorEarning.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(creatorearning.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *CreatorEarningUpsertBulk) UpdateNewValues() *CreatorEarningUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(creatorearning.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(creatorearning.FieldCreatedAt)
			}
			if _, exists := b.mutation.CreatorID(); exists {
				s.SetIgnore(creatorearning.FieldCreatorID)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(creatorearning.FieldKind)
			}
			if _, exists := b.mutation.Reference(); exists {
				s.SetIgnore(creatorearning.FieldReference)
			}
			if _, exists := b.mutation.SourceType(); exists {
				s.SetIgnore(creatorearning.FieldSourceType)
			}
			if _, exists := b.mutation.SourceID(); exists {
				s.SetIgnore(creatorearning.FieldSourceID)
			}
			if _, exists := b.mutation.Description(); exists {
				s.SetIgnore(creatorearning.FieldDescription)
			}
			if _, exists := b.mutation.GrossMinor(); exists {
				s.SetIgnore(creatorearning.FieldGrossMinor)
			}
			if _, exists := b.mutation.NetMinor(); exists {
				s.SetIgnore(creatorearning.FieldNetMinor)
			}
			if _, exists := b.mutation.Unit(); exists {
				s.SetIgnore(creatorearning.FieldUnit)
			}
		}
	}))
	return u
}

